<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {AutomationsClient,AutomationError,type Feedback,type Connector,type Draft,type Workflow,type Approval,type ApprovalDecision,type Configuration,type Authorization,type ProviderSetup,type ConnectionOptions,type TestReceipt,type Execution} from './automations-client';
 import AutomationInternalRun from './AutomationInternalRun.svelte';
 import AutomationSetupCard from './AutomationSetupCard.svelte';import AutomationReviewCard from './AutomationReviewCard.svelte';import AutomationApprovalCard from './AutomationApprovalCard.svelte';import './automations.css';
 export let companyId:string;export let actorId:string;export let conversationId:string;export let accessSignal:AbortSignal;
 export let draftId='';export let workflowId='';export let executionId='';export let people:{id:string;name:string}[]=[];
 /** Native room SSE/JSON may invalidate this view; it never supplies authoritative workflow state. */
 export let nativeEvent:{companyId:string;conversationId:string;cursor:number}|null=null;
 const dispatch=createEventDispatcher<{close:void;denied:{status:number};changed:{companyId:string;conversationId:string;cursor:number};manage:{companyId:string;conversationId:string;workflowId?:string}}>();
 let client:AutomationsClient|undefined,watched:AbortSignal|undefined,mounted=false,scope='',generation=0,session='',lastNative=-1;
 let setupProviders:ProviderSetup[]=[];
 let runReceipts:Record<string,string>={};
 let snapshot:Feedback|null=null,connectors:Connector[]=[],engineAvailable=false,loading=true,busy=false,error='',notice='',live=false,streaming=false;
 let authorization:Authorization|null=null,authorizationFor='',test:TestReceipt|null=null,retry:ReturnType<typeof setTimeout>|undefined,inFlight=false,queued=false;
 $: if(mounted&&(scope!==companyId+'\0'+actorId+'\0'+conversationId||watched!==accessSignal)){reset();scope=companyId+'\0'+actorId+'\0'+conversationId;watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted||!companyId||!conversationId)lost();else{session=localStorage.getItem('token')||'';client=new AutomationsClient(companyId,()=>localStorage.getItem('token')||'',watched);void initialize();}}
 $: if(nativeEvent&&nativeEvent.companyId===companyId&&nativeEvent.conversationId===conversationId&&Number.isSafeInteger(nativeEvent.cursor)&&nativeEvent.cursor>lastNative){lastNative=nativeEvent.cursor;if(client)void refresh();}
 $: selectedDraft=snapshot?.drafts.find(d=>draftId?d.id===draftId:workflowId?d.id===snapshot?.workflows.find(w=>w.id===workflowId)?.draftId:!executionId)||null;
 $: selectedWorkflows=(snapshot?.workflows||[]).filter(w=>workflowId?w.id===workflowId:executionId?snapshot?.executions.some(e=>e.id===executionId&&e.workflowId===w.id):draftId?w.draftId===draftId:true);
 $: selectedExecutions=(snapshot?.executions||[]).filter(e=>executionId?e.id===executionId:workflowId?e.workflowId===workflowId:draftId?selectedWorkflows.some(w=>w.id===e.workflowId):true);
 $: selectedApprovals=(snapshot?.approvals||[]).filter(a=>executionId?a.executionId===executionId:workflowId?a.workflowId===workflowId:draftId?selectedWorkflows.some(w=>w.id===a.workflowId):true);
 $: missingRequested=!!snapshot&&(!!draftId&&!snapshot.drafts.some(d=>d.id===draftId)||!!workflowId&&!snapshot.workflows.some(w=>w.id===workflowId)||!!executionId&&!snapshot.executions.some(e=>e.id===executionId));
 function reset(){generation++;clearTimeout(retry);client?.close();client=undefined;watched?.removeEventListener('abort',lost);snapshot=null;setupProviders=[];runReceipts={};connectors=[];authorization=null;authorizationFor='';test=null;engineAvailable=false;loading=true;busy=false;error='';notice='';live=false;streaming=false;inFlight=false;queued=false;lastNative=-1;}
 function lost(){reset();loading=false;dispatch('close');}
 function fail(cause:unknown){if(cause instanceof AutomationError&&(cause.status===401||cause.status===403)){reset();loading=false;dispatch('denied',{status:cause.status});return;}error=cause instanceof Error?cause.message:'The saved automation status could not be checked.';}
 async function initialize(){const current=client,n=generation;if(!current)return;try{const [catalog,setup]=await Promise.all([current.catalog(),current.connectionSetup().catch(e=>{if(e instanceof AutomationError&&(e.status===401||e.status===403))throw e;return null;})]);if(n!==generation)return;connectors=catalog.connectors;setupProviders=setup?.providers||[];engineAvailable=catalog.engine.available;await refresh();if(n===generation&&snapshot)void watch();}catch(e){if(n===generation){loading=false;fail(e);}}}
 async function refresh(){if(!client)return;if(inFlight){queued=true;return;}const current=client,n=generation;inFlight=true;try{const value=await current.feedback(conversationId);if(n!==generation)return;if(!snapshot||value.cursor>=snapshot.cursor){snapshot=value;if(test&&!value.drafts.some(d=>d.id===test?.draftId&&d.revision===test.revision))test=null;dispatch('changed',{companyId,conversationId,cursor:value.cursor});}error='';}catch(e){if(n===generation)fail(e);}finally{if(n===generation){inFlight=false;loading=false;if(queued){queued=false;void refresh();}}}}
 async function watch(){if(!client||streaming||!snapshot)return;const current=client,n=generation;streaming=true;try{await current.watchFeedback(conversationId,snapshot.cursor,()=>{if(n!==generation)return;live=true;void refresh();});if(n===generation)live=false;}catch(e){if(n===generation){live=false;if(e instanceof AutomationError&&(e.status===401||e.status===403)){fail(e);return;}}}finally{if(n===generation){streaming=false;retry=setTimeout(()=>void watch(),3000);}}}
 async function action(task:(current:AutomationsClient,n:number)=>Promise<void>){if(busy||!client)return;const n=generation,current=client;busy=true;error='';notice='';try{await task(current,n);if(n===generation)await refresh();}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 async function answer(configuration:Configuration){if(!selectedDraft)return;const draft=selectedDraft;await action(async(current,n)=>{await current.answer(draft,configuration);if(n===generation){test=null;authorization=null;}});}
 async function connect(providerId:string,options:ConnectionOptions={}){if(!selectedDraft)return;const draft=selectedDraft;await action(async(current,n)=>{const result=await current.authorize(providerId,conversationId,draft,options);if(n!==generation)return;const setup=await current.connectionSetup().catch(e=>{if(e instanceof AutomationError&&(e.status===401||e.status===403))throw e;return null;});if(n!==generation)return;if(setup)setupProviders=setup.providers;authorization=result;authorizationFor=draft.id+':'+draft.revision+':'+(draft.missing[0]?.id||'');notice=result.status==='CONNECTED'?'Existing company connection verified. Setup resumed.':result.status==='SETUP_UNAVAILABLE'?'Secure provider setup is not available yet. This draft remains saved here.':'';});}
 async function testDraft(draft:Draft){await action(async(current,n)=>{const result=await current.test(draft);if(n===generation)test=result;});}
 async function activate(draft:Draft){await action(async(current,n)=>{await current.activate(draft);if(n===generation)notice=draft.summary.approvalRequired?'Activation confirmed. Each consequential action still requires its own approval.':'New-order notifications activated for this conversation. No per-order approval is required.';});}
 async function runInternal(workflow:Workflow,label:string,key:string){await action(async(current,n)=>{const receipt=await current.runInternal(workflow,label,key);if(n===generation){runReceipts={...runReceipts,[workflow.id]:receipt.id};notice='Internal test submitted. Its exact approval and recorded receipt will update here.';}});}
 async function resume(workflow:Workflow){await action(async(current,n)=>{await current.resume(workflow);if(n===generation)notice=workflow.intent==='shopify_new_order_chat'?'New-order notifications resumed in this conversation.':'Resume confirmed for this workflow.';});}
 async function pause(workflow:Workflow){await action(async(current,n)=>{await current.pause(workflow);if(n===generation)notice='Pause confirmed for this workflow.';});}
 async function decide(approval:Approval,decision:ApprovalDecision){await action(async(current,n)=>{await current.decide(approval,decision);if(n===generation)notice='Your exact decision was recorded. The result will be updated in this conversation.';});}
 function manage(workflow?:Workflow){dispatch('manage',{companyId,conversationId,...(workflow?{workflowId:workflow.id}:{})});}
 const date=(n:number)=>new Date(n*1000).toLocaleString();
 const statusLabel=(value:string)=>({PENDING:'Waiting to start',QUEUED:'Waiting to start',RUNNING:'Running',WAITING_FOR_HUMAN:'Waiting for approval',COMPLETED:'Completed',FAILED:'Could not complete',UNCERTAIN:'Outcome needs confirmation',PARTIAL:'Partially completed',CANCELLED:'Cancelled'} as Record<string,string>)[value]||'Status recorded';
 function statusMessage(execution:Execution){if(execution.status==='UNCERTAIN')return 'An external action may have happened. Check its recorded provider outcome before retrying; this card does not restart work.';if(execution.status==='PARTIAL')return 'Only part of this run completed. Review its verified receipts before continuing.';if(execution.status==='FAILED')return 'This run could not finish. Review the saved workflow and its history before trying again.';if(execution.status==='WAITING_FOR_HUMAN')return 'The workflow is waiting for its assigned approver’s exact decision.';if(execution.status==='RUNNING')return 'The saved workflow is executing. Its recorded outcome will update here.';if(execution.status==='CANCELLED')return 'This execution was cancelled. No new execution has been started by this card.';return '';}
 function checkSession(){if(client&&session!==(localStorage.getItem('token')||''))lost();}
 function focused(){checkSession();if(client)void refresh();}
 function storage(e:StorageEvent){if(e.key==='token'||e.key===null)lost();}
 onMount(()=>{mounted=true;window.addEventListener('storage',storage);window.addEventListener('focus',focused);const timer=setInterval(checkSession,500);return()=>clearInterval(timer);});onDestroy(()=>{reset();window.removeEventListener('storage',storage);window.removeEventListener('focus',focused);});
</script>
<section class="starli-automations chat-feedback" aria-label="Automation in this conversation">
 <div class="sa-heading"><div><span class="sa-eyebrow">STARLI AUTOMATIONS</span><h3>Saved in this conversation</h3></div><div class="feedback-actions"><button disabled={busy||loading} on:click={()=>void refresh()}>Refresh</button><button disabled={busy} on:click={()=>manage()}>Manage</button></div></div>
 {#if loading}<p class="sa-muted" role="status">Checking the saved setup and recorded execution state…</p>{/if}{#if error}<p class="sa-error" role="alert">{error}</p>{/if}{#if notice}<p class="sa-muted" role="status">{notice}</p>{/if}
 {#if snapshot}{#if !live}<p class="sa-muted feedback-freshness">Showing recorded state. Live updates reconnect automatically; Refresh checks the latest saved outcome.</p>{/if}{#if missingRequested}<p class="sa-warning">The requested automation resource is not available in this conversation. Refresh or review company automations.</p>{:else}
 {#if selectedDraft&&!workflowId&&!executionId}<AutomationSetupCard draft={selectedDraft} {setupProviders} {connectors} {people} {busy} authorization={authorizationFor===selectedDraft.id+':'+selectedDraft.revision+':'+(selectedDraft.missing[0]?.id||'')?authorization:null} on:answer={e=>answer(e.detail)} on:connect={e=>connect(e.detail.providerId,{shopDomain:e.detail.shopDomain,expectedSetupRevision:e.detail.expectedSetupRevision})} on:refresh={()=>{authorization=null;void initialize();}}/><AutomationReviewCard draft={selectedDraft} {test} {busy} {engineAvailable} on:test={e=>testDraft(e.detail)} on:activate={e=>activate(e.detail)} on:edit={()=>manage()}/>{/if}
 {#each selectedWorkflows as workflow}{#if workflow.intent==='shopify_new_order_chat'}<AutomationReviewCard {workflow} {busy} {engineAvailable} on:pause={e=>pause(e.detail)} on:resume={e=>resume(e.detail)} on:history={()=>manage(workflow)} on:edit={()=>manage(workflow)}/>{:else}<div class="workflow-status"><div><strong>{workflow.name}</strong><p class="sa-muted">{workflow.status==='UNCERTAIN'?'Activation outcome needs confirmation':workflow.status==='PROVISIONING'?'Activation in progress':workflow.status.toLowerCase()} · revision {workflow.revision}</p></div><button disabled={busy||!workflow.actions.canPause} on:click={()=>pause(workflow)}>Pause</button></div>{/if}{#if workflow.intent==='internal_approval_test'&&workflow.actions.canRun}<AutomationInternalRun {workflow} {busy} receiptId={runReceipts[workflow.id]||''} on:run={e=>runInternal(e.detail.workflow,e.detail.label,e.detail.key)}/>{/if}{/each}
 {#each selectedExecutions as execution}<article class="execution" aria-label="Automation execution"><div class="sa-heading"><strong>{statusLabel(execution.status)}</strong><span class="sa-badge">Version {execution.workflowVersion}</span></div>{#if statusMessage(execution)}<p class:sa-warning={execution.status==='UNCERTAIN'||execution.status==='PARTIAL'} class="sa-muted">{statusMessage(execution)}</p>{/if}{#if execution.orderSummary}<dl class="sa-details"><div><dt>Shopify store</dt><dd>{execution.orderSummary.shopDomain}</dd></div><div><dt>New order</dt><dd>{execution.orderSummary.orderName} · {execution.orderSummary.orderId}</dd></div><div><dt>Order total</dt><dd>{execution.orderSummary.amount} {execution.orderSummary.currency}</dd></div></dl>{/if}{#if execution.receipt?.status==='VERIFIED'}<dl class="sa-details"><div><dt>Verified operation</dt><dd>{execution.receipt.operation==='refund'?'Refund':execution.receipt.operation==='ticket'?'Support ticket':execution.receipt.operation==='internal_test_receipt'?'Internal test receipt':execution.receipt.operation==='slack_message_send'?'Slack message':execution.receipt.operation==='shopify_order_chat_notification'?'New-order notification in this conversation':'Recorded action'}</dd></div><div><dt>Provider resource</dt><dd>{execution.receipt.resourceId}</dd></div><div><dt>Verified</dt><dd>{date(execution.receipt.verifiedAt)}</dd></div></dl>{/if}<p class="sa-reference">Execution {execution.id} · updated {date(execution.updatedAt)}</p></article>{/each}
 {#each selectedApprovals as approval}<AutomationApprovalCard {approval} {actorId} {people} {busy} on:decision={e=>decide(e.detail.approval,e.detail.decision)}/>{/each}
 {#if !selectedDraft&&!selectedWorkflows.length&&!selectedExecutions.length&&!selectedApprovals.length}<p class="sa-muted">No saved automation setup or runs were found in this conversation.</p>{/if}
 {/if}{/if}
</section>
<style>.chat-feedback{width:100%;max-width:780px;min-width:0;padding:18px;background:#fafbfd;border:1px solid #e6ebf4;border-radius:13px;margin:12px 0}.feedback-actions{display:flex;gap:6px}.feedback-freshness{font-size:10px!important;margin-top:14px!important}.workflow-status{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:15px;border:1px solid #e6ebf4;border-radius:9px;background:white;margin-top:15px}.workflow-status .sa-muted{font-size:10px}.execution{border:1px solid #e6ebf4;border-radius:10px;padding:17px;background:white;margin-top:15px}.execution .sa-reference{margin-top:10px}.execution .sa-details{padding:12px 0}.chat-feedback :global(.setup-card),.chat-feedback :global(.review-card),.chat-feedback :global(.approval-card){margin-bottom:0}.chat-feedback .sa-heading{min-width:0}@media(max-width:500px){.chat-feedback{padding:13px}.chat-feedback>.sa-heading{flex-direction:column;gap:12px}.execution{padding:14px}.feedback-actions{align-self:flex-end}.workflow-status{padding:13px}}</style>
